head.b:skin:
    /*---------------------------------------------------------
    VARIÁVEIS DO BLOGGER THEME DESIGNER
    -----------------------------------------------------------*/
    /*
    <Group description="Fundo e Cores Base" selector="body">
        <Variable name="body.background" description="Fundo Geral" type="background" color="#f8f9fa" default="$(color) none repeat scroll top left" value="$(color) none repeat scroll top left"/>
        <Variable name="theme.primary" description="Cor Principal (Destaques)" type="color" default="#e74c3c" value="#e74c3c"/>
        <Variable name="theme.accent" description="Cor Secundária (Tags)" type="color" default="#2c3e50" value="#2c3e50"/>
        <Variable name="theme.text" description="Cor do Texto Principal" type="color" default="#333333" value="#333333"/>
        <Variable name="theme.link" description="Cor dos Links" type="color" default="#0d6efd" value="#0d6efd"/>
        <Variable name="theme.linkHover" description="Cor dos Links (Ao passar o mouse)" type="color" default="#0a58ca" value="#0a58ca"/>
        <Variable name="theme.border" description="Cor das Bordas/Linhas" type="color" default="#dee2e6" value="#dee2e6"/>
    </Group>

    <Group description="Cores do Cabeçalho e Rodapé" selector="body">
        <Variable name="header.bg" description="Fundo do Cabeçalho" type="color" default="#ffffff" value="#ffffff"/>
        <Variable name="footer.bg" description="Fundo do Rodapé" type="color" default="#212529" value="#212529"/>
        <Variable name="footer.text" description="Texto do Rodapé" type="color" default="#f8f9fa" value="#f8f9fa"/>
    </Group>

    <Group description="Tipografia" selector="body">
        <Variable name="body.font" description="Fonte do Texto" type="font" default="normal normal 16px 'Segoe UI', Roboto, Helvetica, Arial, sans-serif" value="normal normal 16px &#39;Segoe UI&#39;, Roboto, Helvetica, Arial, sans-serif"/>
        <Variable name="heading.font" description="Fonte dos Títulos (H1-H6)" type="font" default="normal bold 24px 'Segoe UI', Roboto, Helvetica, Arial, sans-serif" value="normal bold 24px &#39;Segoe UI&#39;, Roboto, Helvetica, Arial, sans-serif"/>
        <Variable name="nav.font" description="Fonte do Menu Principal" type="font" default="normal 600 15px 'Segoe UI', Roboto, Helvetica, Arial, sans-serif" value="normal 600 15px &#39;Segoe UI&#39;, Roboto, Helvetica, Arial, sans-serif"/>
    </Group>
    */

    /*---------------------------------------------------------
    MAPEAMENTO PARA VARIÁVEIS CSS MODERNAS (:root)
    -----------------------------------------------------------*/
    :root {
        --vm-primary: $(theme.primary);
        --vm-accent: $(theme.accent);
        --vm-text: $(theme.text);
        --vm-link: $(theme.link);
        --vm-link-hover: $(theme.linkHover);
        --vm-border: $(theme.border);
        --vm-header-bg: $(header.bg);
        --vm-footer-bg: $(footer.bg);
        --vm-footer-text: $(footer.text);
    }

    /*---------------------------------------------------------
    ESTILOS GERAIS
    -----------------------------------------------------------*/
    body {
        background: $(body.background);
        color: var(--vm-text);
        font: $(body.font);
        transition: background-color 0.3s ease, color 0.3s ease;
    }

    h1, h2, h3, h4, h5, h6 { 
        font: $(heading.font); 
        color: var(--vm-text);
    }

    a { 
        color: var(--vm-link); 
        text-decoration: none; 
        transition: color 0.2s ease; 
    }
    a:hover { color: var(--vm-link-hover); }

    /*---------------------------------------------------------
    DARK MODE (Sobrescrita de Variáveis)
    -----------------------------------------------------------*/
    [data-bs-theme="dark"] body {
        --vm-text: #e0e0e0;
        --vm-border: #333333;
        --vm-header-bg: #1e1e1e;
        --vm-footer-bg: #0a0a0a;
        --vm-footer-text: #cccccc;
        background-color: #121212 !important;
        background-image: none !important; /* Remove imagens de fundo claras no dark mode */
    }

    [data-bs-theme="dark"] h1, 
    [data-bs-theme="dark"] h2, 
    [data-bs-theme="dark"] h3, 
    [data-bs-theme="dark"] h4, 
    [data-bs-theme="dark"] h5, 
    [data-bs-theme="dark"] h6 {
        color: #ffffff;
    }

    /*---------------------------------------------------------
    CABEÇALHO, MENU E RODAPÉ
    -----------------------------------------------------------*/
    .site-header { 
        background-color: var(--vm-header-bg) !important;
        border-bottom: 3px solid var(--vm-primary) !important; 
    }

    .search-bar { max-width: 300px; }

    .navbar { font: $(nav.font); border-bottom-color: var(--vm-border) !important; }
    .navbar a { color: var(--vm-text); }
    .navbar a:hover { color: var(--vm-primary); }

    footer {
        background-color: var(--vm-footer-bg) !important;
        color: var(--vm-footer-text) !important;
        border-top: 1px solid var(--vm-border);
    }
    footer a { color: var(--vm-footer-text); opacity: 0.8; }
    footer a:hover { color: var(--vm-primary); opacity: 1; }

    /*---------------------------------------------------------
    POSTAGENS E WIDGETS
    -----------------------------------------------------------*/
    .post-body img { 
        max-width: 100%; 
        height: auto; 
        border-radius: 8px; 
    }

    /* Corrige cores de borda em elementos do Bootstrap */
    .border-bottom, .border-top { border-color: var(--vm-border) !important; }

/*---------------------------------------------------------
    BLOCOS DE REVISTA (MAGAZINE BLOCKS) - ESTRUTURA E ANIMAÇÕES
    -----------------------------------------------------------*/

    /* Contentor Base do Cartão */
    .mag-card {
        position: relative;
        border-radius: 8px; /* Cantos arredondados premium */
        overflow: hidden;   /* Impede que a imagem transborde ao fazer zoom */
        display: block;
        height: 100%;
        background-color: var(--vm-header-bg);
        border: 1px solid var(--vm-border);
        transition: transform 0.3s ease, box-shadow 0.3s ease;
    }

    /* Tratamento de Imagens em Alta Resolução */
    .mag-card img.mag-img {
        width: 100%;
        height: 100%;
        object-fit: cover; /* Garante que a imagem preencha o espaço sem distorcer */
        transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94); /* Curva de animação cinematográfica */
    }

    /* Interação (Hover): Zoom subtil e Sombra */
    .mag-card:hover {
        box-shadow: 0 15px 30px rgba(0,0,0,0.1);
        transform: translateY(-3px); /* Levanta ligeiramente o cartão */
    }
    .mag-card:hover img.mag-img {
        transform: scale(1.05); /* Zoom na imagem sem sair do cartão */
    }

    [data-bs-theme="dark"] .mag-card:hover {
        box-shadow: 0 15px 30px rgba(0,0,0,0.5);
    }

    /*---------------------------------------------------------
    ESTILOS PARA O HERO TOP (Destaques Gigantes)
    -----------------------------------------------------------*/

    /* Overlay escuro para legibilidade do título sobre a foto */
    .mag-overlay {
        position: absolute;
        bottom: 0;
        left: 0;
        width: 100%;
        padding: 30px 20px 20px;
        background: linear-gradient(to bottom, rgba(0,0,0,0) 0%, rgba(0,0,0,0.85) 100%);
        z-index: 2;
        display: flex;
        flex-direction: column;
        justify-content: flex-end;
    }

    /* Etiqueta de Categoria Flutuante (Ex: "TECNOLOGIA") */
    .mag-badge {
        position: absolute;
        top: 15px;
        left: 15px;
        background-color: var(--vm-primary);
        color: #fff;
        padding: 4px 10px;
        font-size: 0.75rem;
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: 0.5px;
        border-radius: 4px;
        z-index: 3;
        box-shadow: 0 2px 5px rgba(0,0,0,0.2);
    }

    /* Títulos dos Artigos em Destaque */
    .mag-title {
        color: #fff;
        font-weight: 800;
        line-height: 1.25;
        margin-bottom: 5px;
        text-shadow: 0 2px 4px rgba(0,0,0,0.6);
    }

    /* Efeito de Sublinhado Mágico nos Títulos */
    .mag-title a {
        color: inherit;
        background-image: linear-gradient(transparent calc(100% - 3px), var(--vm-primary) 3px);
        background-repeat: no-repeat;
        background-size: 0 100%;
        transition: background-size 0.4s ease;
    }

    .mag-card:hover .mag-title a {
        background-size: 100% 100%; /* O sublinhado preenche o título ao passar o rato */
    }

    /*---------------------------------------------------------
    ESTILOS PARA A GRELHA PADRÃO (Resumos e Meta)
    -----------------------------------------------------------*/
    .mag-content {
        padding: 15px;
    }

    .mag-title-dark {
        color: var(--vm-text);
        font-weight: 700;
        font-size: 1.25rem;
        line-height: 1.3;
        margin-bottom: 8px;
    }

    .mag-title-dark a { color: var(--vm-text); }
    .mag-title-dark a:hover { color: var(--vm-primary); }

    /* Truncamento Inteligente de Linhas (Line Clamp) */
    .mag-excerpt {
        display: -webkit-box;
        -webkit-line-clamp: 3; /* Mostra apenas 3 linhas e adiciona "..." */
        -webkit-box-orient: vertical;
        overflow: hidden;
        font-size: 0.9rem;
        color: var(--vm-text);
        opacity: 0.75;
        margin-bottom: 0;
    }

    /* Metadados (Data, Autor) */
    .mag-meta {
        font-size: 0.8rem;
        color: var(--vm-text);
        opacity: 0.6;
        margin-top: 10px;
        display: flex;
        align-items: center;
        gap: 10px;
    }


  /*---------------------------------------------------------
    REMOVER ÍCONES DE EDIÇÃO (QUICK EDIT) DO FRONT-END
    -----------------------------------------------------------*/
    .quickedit, 
    .widget-item-control, 
    .item-control,
    .item-control.blog-admin { 
        display: none !important; 
        height: 0 !important;
        width: 0 !important;
        opacity: 0 !important;
        visibility: hidden !important;
    }

/*---------------------------------------------------------
FORMULÁRIO DE CONTATO PREMIUM (VIRAL MAGAZINE)
-----------------------------------------------------------*/
/* Container do Gadget */
.ContactForm {
    max-width: 100%;
    margin: 0 auto;
}

/* Esconde o título padrão se quiser algo mais limpo */
.ContactForm h2.title { display: none; }

/* Estilização dos Campos (Inputs e Textarea) */
.ContactForm input[type="text"], 
.ContactForm input[type="email"], 
.ContactForm textarea {
    width: 100%;
    background-color: var(--vm-header-bg);
    border: 1px solid var(--vm-border);
    color: var(--vm-text);
    padding: 12px 15px;
    border-radius: 8px;
    margin-bottom: 15px;
    font-family: inherit;
    font-size: 0.95rem;
    transition: all 0.3s ease;
    box-shadow: none;
    -webkit-appearance: none;
}

/* Efeito de Foco (High-End) */
.ContactForm input:focus, 
.ContactForm textarea:focus {
    outline: none;
    border-color: var(--vm-primary);
    box-shadow: 0 0 0 3px rgba(231, 76, 60, 0.1); /* Cor primária com transparência */
    background-color: var(--vm-header-bg);
}

/* Botão de Enviar */
.ContactForm input[type="button"], 
.ContactForm input[type="submit"] {
    background-color: var(--vm-primary);
    color: #fff;
    border: none;
    padding: 12px 30px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    border-radius: 50px; /* Estilo pílula */
    cursor: pointer;
    transition: all 0.3s ease;
    width: auto;
    display: inline-block;
}

.ContactForm input[type="button"]:hover, 
.ContactForm input[type="submit"]:hover {
    background-color: var(--vm-accent);
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(0,0,0,0.1);
}

/* Mensagens de Erro e Sucesso */
.contact-form-error-message-with-border {
    background: #f8d7da !important;
    border: 1px solid #f5c6cb !important;
    color: #721c24 !important;
    border-radius: 8px;
    padding: 10px !important;
    font-size: 0.85rem;
}

.contact-form-success-message {
    background: #d4edda !important;
    border: 1px solid #c3e6cb !important;
    color: #155724 !important;
    border-radius: 8px;
    padding: 10px !important;
}

/* Ajuste para Dark Mode */
[data-bs-theme="dark"] .ContactForm input,
[data-bs-theme="dark"] .ContactForm textarea {
    background-color: #1e1e1e;
    border-color: #333;
}

/*---------------------------------------------------------
GADGET DE ESTATÍSTICAS (NATIVO) - VIRAL MAGAZINE
-----------------------------------------------------------*/
#Stats1 {
    margin-bottom: 2rem;
}

/* Título do Gadget */
#Stats1 h2 {
    font-size: 1.2rem;
    font-weight: 700;
    margin-bottom: 1rem;
    color: var(--vm-text);
}

/* O Card Principal */
#Stats1 .widget-content {
    background-color: var(--vm-header-bg, #ffffff);
    border: 1px solid var(--vm-border, #eaeaea);
    border-radius: 10px;
    padding: 20px;
    box-shadow: 0 4px 10px rgba(0,0,0,0.03);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

#Stats1 .widget-content:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 20px rgba(0,0,0,0.08);
}

/* Força Flexbox quando o Blogger tira o display:none via AJAX */
div[id^="Stats1_content"] {
    display: flex !important; 
    align-items: center;
    justify-content: space-between;
    gap: 15px;
}

/* Fundo sutil para o Gráfico (Sparkline) */
span[id^="Stats1_sparklinespan"] {
    background: rgba(13, 110, 253, 0.08); /* Azul translúcido */
    border-radius: 6px;
    padding: 5px 10px;
    display: flex !important;
    align-items: center;
    justify-content: center;
}

/* Estilização do Contador Numérico */
#Stats1 .counter-wrapper {
    font-size: 1.8rem;
    font-weight: 900;
    color: var(--vm-primary, #0d6efd);
    letter-spacing: 1px;
}

/* Truque: Se estiver usando as "imagens" antigas de números do Blogger, isso as alinha e suaviza */
#Stats1 .graph-counter-wrapper img {
    vertical-align: middle;
    margin: 0 1px;
    border-radius: 2px;
    /* Tira um pouco daquele ar de "ano 2005" dos números */
    filter: drop-shadow(0px 2px 2px rgba(0,0,0,0.1)); 
}

/* Esconde o ícone de chave de fenda (Quickedit) */
#Stats1 .quickedit {
    display: none !important;
}

/* Adaptação automática para o Dark Mode */
[data-bs-theme="dark"] #Stats1 .widget-content {
    background-color: #1e1e1e;
    border-color: #333;
}

[data-bs-theme="dark"] span[id^="Stats1_sparklinespan"] {
    background: rgba(255, 255, 255, 0.05);
}

/*---------------------------------------------------------
    GADGET DE MARCADORES / CATEGORIAS (VIRAL MAGAZINE)
    -----------------------------------------------------------*/

    /* 1. MODO NUVEM (CLOUD) - Estilo Pílulas/Badges */
    .Label .cloud-label-widget-content {
        display: flex;
        flex-wrap: wrap;
        gap: 10px;
    }

    /* O container de cada tag */
    .Label .label-size {
        display: inline-flex;
        align-items: center;
        background-color: var(--vm-header-bg);
        border: 1px solid var(--vm-border);
        padding: 6px 16px;
        border-radius: 50px; /* Arredondamento premium */
        font-size: 0.85rem !important; /* Anula tamanhos bizarros do Blogger */
        font-weight: 600;
        transition: all 0.3s ease;
        cursor: pointer;
    }

    /* O link dentro da tag */
    .Label .label-size a {
        color: var(--vm-text);
        text-decoration: none;
        transition: color 0.3s ease;
    }

    /* O contador de posts na Nuvem (ex: "(5)") */
    .Label .label-size .label-count {
        margin-left: 6px;
        font-size: 0.75rem;
        opacity: 0.6;
        color: var(--vm-text);
    }

    /* Hover da Nuvem */
    .Label .label-size:hover {
        background-color: var(--vm-primary);
        border-color: var(--vm-primary);
        transform: translateY(-2px);
        box-shadow: 0 4px 10px rgba(0,0,0,0.15);
    }

    .Label .label-size:hover a,
    .Label .label-size:hover .label-count {
        color: #ffffff; /* Fica branco ao passar o mouse */
    }


    /* 2. MODO LISTA (LIST) - Estilo Blocos de Navegação */
    .Label .list-label-widget-content ul {
        list-style: none;
        padding: 0;
        margin: 0;
    }

    .Label .list-label-widget-content li {
        margin-bottom: 10px;
    }

    .Label .list-label-widget-content li a {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 12px 18px;
        background-color: var(--vm-header-bg);
        border: 1px solid var(--vm-border);
        border-radius: 8px;
        color: var(--vm-text);
        text-decoration: none;
        font-weight: 600;
        transition: all 0.3s ease;
    }

    /* O contador de posts na Lista */
    .Label .list-label-widget-content .label-count {
        background-color: var(--vm-border);
        color: var(--vm-text);
        padding: 2px 10px;
        border-radius: 20px;
        font-size: 0.8rem;
        transition: all 0.3s ease;
    }

    /* Hover da Lista */
    .Label .list-label-widget-content li a:hover {
        background-color: var(--vm-primary);
        border-color: var(--vm-primary);
        color: #ffffff;
        transform: translateX(5px); /* Efeito de seta apontando */
    }

    .Label .list-label-widget-content li a:hover .label-count {
        background-color: rgba(255,255,255,0.2);
        color: #ffffff;
    }

    /* 3. COMPATIBILIDADE DARK MODE */
    [data-bs-theme="dark"] .Label .label-size,
    [data-bs-theme="dark"] .Label .list-label-widget-content li a {
        background-color: #1e1e1e;
        border-color: #333;
    }
    [data-bs-theme="dark"] .Label .list-label-widget-content .label-count {
        background-color: #333;
    }

/*---------------------------------------------------------
    CITAÇÕES E BLOCKQUOTES (ESTILO EDITORIAL)
    -----------------------------------------------------------*/
    .post-body blockquote {
        position: relative;
        background-color: rgba(0, 0, 0, 0.03); /* Fundo super suave e translúcido */
        border-left: 5px solid var(--vm-primary); /* Linha destacada na cor principal */
        margin: 2.5rem 0;
        padding: 1.5rem 2rem 1.5rem 3.5rem; /* Espaço extra na esquerda para a aspa */
        border-radius: 0 8px 8px 0;
        font-size: 1.2rem; /* Fonte ligeiramente maior que o texto normal */
        font-style: italic;
        font-weight: 500;
        color: var(--vm-text);
        line-height: 1.7;
        box-shadow: 0 4px 15px rgba(0,0,0,0.02);
    }

    /* O ícone de aspas gigante no fundo (Pseudo-elemento) */
    .post-body blockquote::before {
        content: "\201C"; /* Código Unicode para aspas duplas de abertura */
        position: absolute;
        top: -5px;
        left: 15px;
        font-family: Georgia, "Times New Roman", serif; /* Fonte clássica para a aspa */
        font-size: 5rem;
        font-weight: 900;
        color: var(--vm-primary);
        opacity: 0.15; /* Transparência para funcionar como marca d'água */
        line-height: 1;
        z-index: 0;
    }

    /* Garante que os parágrafos dentro do blockquote fiquem acima da aspa */
    .post-body blockquote p {
        margin-bottom: 0;
        position: relative;
        z-index: 1; 
    }

    /* Compatibilidade perfeita com o Dark Mode */
    [data-bs-theme="dark"] .post-body blockquote {
        background-color: rgba(255, 255, 255, 0.04);
        border-left-color: var(--vm-primary);
    }

    /* Esconde a Navbar nativa do Blogger (Lixo visual e de performance) */
    #navbar-iframe { display: none !important; }
/*---------------------------------------------------------
  COMPONENTE: VÍDEO RESPONSIVO (16:9 PREMIUM)
-----------------------------------------------------------*/
.mag-video-wrapper {
    position: relative;
    width: 100%;
    padding-bottom: 56.25%; /* Matemática exata para a proporção 16:9 */
    height: 0;
    border-radius: var(--radius, 12px); /* Arredondamento premium */
    overflow: hidden;
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.08); /* Sombra elegante */
    margin: 2rem 0; /* Espaçamento para respirar no texto */
    background-color: #000; /* Fundo preto enquanto o vídeo carrega */
}

.mag-video-wrapper iframe {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    border: none;
}

b:includable.script:
function googleTranslateElementInit() {
  new google.translate.TranslateElement({
    pageLanguage: '',
    autoDisplay: 'true',
    layout: google.translate.TranslateElement.InlineLayout.
  }, 'google_translate_element');
}

body.script:
//
document.getElementById('theme-toggle').addEventListener('click', () => {
    const currentTheme = document.documentElement.getAttribute('data-bs-theme');
    const newTheme = currentTheme === 'dark' ? 'light' : 'dark';
    document.documentElement.setAttribute('data-bs-theme', newTheme);
    localStorage.setItem('theme', newTheme);

    // Troca o ícone dinamicamente
    const icon = document.querySelector('#theme-toggle i');
    icon.className = newTheme === 'dark' ? 'bi bi-sun-fill' : 'bi bi-moon-stars-fill';
});
//

//
document.addEventListener('DOMContentLoaded', () => {

    // -------------------------------------------------------------
    // FUNÇÃO SNIPER: Força Alta Resolução em QUALQUER servidor do Google
    // -------------------------------------------------------------
    const getHighResImage = (post, width, height) => {
        let imgUrl = 'https://placehold.co/' + width + 'x' + height + '/1e1e1e/FFF?text=News';

        // 1. Tenta pegar a miniatura nativa
        if (post.media$thumbnail) {
            imgUrl = post.media$thumbnail.url;
        } 
        // 2. Fallback: Se não tiver miniatura, raspa a primeira <img> do HTML do post
        else if (post.content && post.content.$t.match(/<img.+?src="([^"]+)"/)) {
            imgUrl = post.content.$t.match(/<img.+?src="([^"]+)"/)[1];
        }

        // 3. O Tratamento Regex (Funciona para links antigos e novos do Google)
        // Substitui parâmetros antigos (ex: /s72-c/)
        imgUrl = imgUrl.replace(/\/(s|w|h)\d+.*?(\/)/g, `/w${width}-h${height}-c$2`);
        // Substitui parâmetros novos (ex: =s72-w400-c)
        imgUrl = imgUrl.replace(/=(s|w|h)\d+.*$/g, `=w${width}-h${height}-c`);

        return imgUrl;
    };

    // Função Central para buscar e renderizar posts
    const fetchMagazinePosts = async (containerId, maxResults, layoutType, label = '') => {
        const container = document.getElementById(containerId);
        if (!container) return;

        container.innerHTML = '<div class="d-flex justify-content-center py-5"><div class="spinner-grow text-primary" role="status"><span class="visually-hidden">A carregar...</span></div></div>';

        let feedUrl = `/feeds/posts/default?alt=json&max-results=${maxResults}`;
        if (label !== '') feedUrl = `/feeds/posts/default/-/${label}?alt=json&max-results=${maxResults}`;

        try {
            const response = await fetch(feedUrl);
            if (!response.ok) throw new Error('Falha na rede');
            const data = await response.json();
            const posts = data.feed.entry || [];

            let html = '';

            if (posts.length === 0) {
                container.innerHTML = '<div class="alert alert-secondary">Nenhum artigo encontrado nesta seção.</div>';
                return;
            }

            // LAYOUT 1: HERO TOP
            if (layoutType === 'hero') {
                html += '<div class="row g-3">';
                posts.forEach((post, index) => {
                    let title = post.title.$t;
                    let link = post.link.find(l => l.rel === 'alternate').href;

                    // Chamando nossa função Sniper (Pede imagem de 800x600)
                    let img = getHighResImage(post, 800, 600);

                    let category = post.category && post.category.length > 0 ? post.category[0].term : 'Destaque';
                    let dateObj = new Date(post.published.$t);
                    let formattedDate = dateObj.toLocaleDateString('pt-BR', {day: '2-digit', month: 'short', year: 'numeric'});
                    let author = post.author[0].name.$t;

                    let colClass = index === 0 ? 'col-lg-8' : 'col-lg-4 d-none d-lg-block';
                    let heightStyle = index === 0 ? 'height: 420px;' : 'height: 202px;';
                    let marginClass = index === 1 ? 'mb-3' : '';

                    if (index === 0) {
                        html += `<div class="${colClass}">
                                    <article class="mag-card border-0" style="${heightStyle}">
                                        <a href="${link}" class="d-block h-100 text-decoration-none">
                                            <span class="mag-badge">${category}</span>
                                            <img src="${img}" class="mag-img" alt="${title}" loading="lazy">
                                            <div class="mag-overlay">
                                                <h2 class="mag-title fs-2"><span style="background-image: none; color: white;">${title}</span></h2>
                                                <div class="mag-meta text-white-50 mt-2">
                                                    <i class="bi bi-person-circle"></i> ${author} &nbsp;&bull;&nbsp; <i class="bi bi-clock"></i> ${formattedDate}
                                                </div>
                                            </div>
                                        </a>
                                    </article>
                                 </div>`;
                        if(posts.length > 1) html += `<div class="col-lg-4 d-flex flex-column">`; 
                    } else {
                        html += `<article class="mag-card border-0 ${marginClass}" style="${heightStyle}">
                                    <a href="${link}" class="d-block h-100 text-decoration-none">
                                        <span class="mag-badge bg-dark">${category}</span>
                                        <img src="${img}" class="mag-img" alt="${title}" loading="lazy">
                                        <div class="mag-overlay" style="padding: 20px 15px 15px;">
                                            <h3 class="mag-title fs-5"><span style="background-image: none; color: white;">${title}</span></h3>
                                        </div>
                                    </a>
                                 </article>`;
                    }
                    if (index === posts.length - 1 && posts.length > 1) html += `</div>`; 
                });
                html += '</div>';
            }

            // LAYOUT 2: GRID PADRÃO
            if (layoutType === 'grid') {
                html += '<div class="row g-4">';
                posts.forEach(post => {
                    let title = post.title.$t;
                    let link = post.link.find(l => l.rel === 'alternate').href;
                    let snippet = post.summary ? post.summary.$t.replace(/<[^>]*>?/gm, '').substring(0, 120) + '...' : '';

                    // Chamando nossa função Sniper (Pede imagem de 600x400)
                    let img = getHighResImage(post, 600, 400);

                    let category = post.category && post.category.length > 0 ? post.category[0].term : 'Notícia';
                    let dateObj = new Date(post.published.$t);
                    let formattedDate = dateObj.toLocaleDateString('pt-BR', {day: '2-digit', month: 'short'});

                    html += `<div class="col-md-6">
                                <article class="mag-card h-100 shadow-sm">
                                    <a href="${link}" class="d-block position-relative" style="height: 220px;">
                                        <span class="mag-badge">${category}</span>
                                        <img src="${img}" class="mag-img" alt="${title}" loading="lazy">
                                    </a>
                                    <div class="mag-content">
                                        <h3 class="mag-title-dark"><a href="${link}">${title}</a></h3>
                                        <p class="mag-excerpt">${snippet}</p>
                                        <div class="mag-meta">
                                            <i class="bi bi-calendar3"></i> ${formattedDate}
                                        </div>
                                    </div>
                                </article>
                             </div>`;
                });
                html += '</div>';
            }

            container.innerHTML = html;

        } catch (error) {
            console.error('Viral Magazine - Erro de Fetch:', error);
            container.innerHTML = `<div class="alert alert-danger border-0 border-start border-danger border-4"><i class="bi bi-exclamation-triangle"></i> Falha ao carregar artigos. Verifique se o blog é público.</div>`;
        }
    };

    // INICIALIZADOR
    if (window.location.pathname === '/' || window.location.pathname === '/index.html') {
        fetchMagazinePosts('js-hero-grid', 3, 'hero');
        // fetchMagazinePosts('mag-block-1', 4, 'grid', 'Tecnologia'); 
        // fetchMagazinePosts('mag-block-2', 4, 'grid');
    }
});
