document.addEventListener('DOMContentLoaded', () => {
    const relatedContainer = document.getElementById('vm-related-posts');

    // Só executa se o container existir (ou seja, dentro de um post)
    if (relatedContainer) {
        const currentUrl = window.location.href.split('?')[0]; // Pega a URL atual para não repetir o post
        const label = relatedContainer.getAttribute('data-label');

        if (!label) {
            relatedContainer.innerHTML = ''; return;
        }

        // Pede 4 posts à API (caso um deles seja o post atual, temos 3 de reserva)
        const feedUrl = `/feeds/posts/default/-/${encodeURIComponent(label)}?alt=json&max-results=4`;

        fetch(feedUrl)
            .then(response => response.json())
            .then(data => {
                const posts = data.feed.entry || [];
                let html = '';
                let count = 0;

                posts.forEach(post => {
                    let link = post.link.find(l => l.rel === 'alternate').href;

                    // Ignora o post que o usuário já está lendo e limita a 3 cards
                    if (link.split('?')[0] === currentUrl || count >= 3) return;

                    let title = post.title.$t;
                    // O Sniper de Imagem embutido (corta para 400x250 pixels)
                    let img = post.media$thumbnail ? post.media$thumbnail.url.replace(/\/(s|w|h)\d+.*?(\/)/g, '/w400-h250-c$2').replace(/=(s|w|h)\d+.*$/g, '=w400-h250-c') : 'https://placehold.co/400x250/1e1e1e/FFF?text=News';

                    // Usa o nosso CSS Premium (.mag-card)
                    html += `
                    <div class="col-md-4">
                        <article class="mag-card h-100 shadow-sm border-0">
                            <a href="${link}" class="d-block" style="height: 160px; overflow: hidden; border-radius: 8px 8px 0 0;">
                                <img src="${img}" class="w-100 h-100 mag-img" style="object-fit: cover;" alt="${title}" loading="lazy">
                            </a>
                            <div class="p-3 bg-body border border-top-0" style="border-radius: 0 0 8px 8px;">
                                <h3 class="h6 fw-bold mb-0" style="display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; line-height: 1.4;">
                                    <a href="${link}" class="text-body text-decoration-none mag-title-dark">${title}</a>
                                </h3>
                            </div>
                        </article>
                    </div>`;
                    count++;
                });

                if (count === 0) {
                    relatedContainer.innerHTML = '<div class="col-12 text-muted small">Nenhuma postagem relacionada encontrada.</div>';
                } else {
                    relatedContainer.innerHTML = html;
                }
            })
            .catch(err => {
                console.error('Erro nos Artigos Relacionados:', err);
                relatedContainer.innerHTML = '';
            });
    }
});
